import {esc,weatherName,valueText} from './weather-tools.js';
import {fotoDataURL} from './photo-tools.js';
import {sendObservation} from './offline.js';
import {reportHaptic} from './ui-feedback.js';
export function coverCrop(w,h,targetW=1080,targetH=1920){const scale=Math.max(targetW/w,targetH/h);return {x:(targetW-w*scale)/2,y:(targetH-h*scale)/2,w:w*scale,h:h*scale}}
const asBlob=(canvas,quality=.88)=>new Promise((resolve,reject)=>canvas.toBlob(blob=>blob?resolve(blob):reject(Error('Immagine non disponibile.')),'image/jpeg',quality));
export async function openPostcard(file,ctx){
 let url='',blob=null,phenomenon='',busy=false,published=false;
 const {place,weather}=ctx.get(),city={...place},current=weather?.current?{...weather.current}:null,created=Date.now(),id=crypto.randomUUID();
 const dialog=document.createElement('dialog');dialog.className='sky-postcard';dialog.setAttribute('aria-label','La tua cartolina del cielo');dialog.innerHTML='<button class="postcard-close" aria-label="Chiudi cartolina">×</button><div class="postcard-layout"><div class="postcard-preview"><p role="status">Preparo la tua cartolina…</p></div><section class="postcard-actions"><h1>Il tuo cielo</h1><p class="postcard-status" role="status"></p></section></div>';document.body.append(dialog);dialog.showModal();const close=()=>dialog.close();dialog.querySelector('.postcard-close').onclick=close;dialog.addEventListener('close',()=>{if(url)URL.revokeObjectURL(url);dialog.remove()},{once:true});
 try{
  const bitmap=await createImageBitmap(file);const canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1920;const x=canvas.getContext('2d');if(!x){bitmap.close();throw Error('Foto non disponibile su questo dispositivo.')}
  const crop=coverCrop(bitmap.width,bitmap.height);x.drawImage(bitmap,crop.x,crop.y,crop.w,crop.h);bitmap.close();
  const shade=x.createLinearGradient(0,0,0,1920);shade.addColorStop(0,'rgba(3,10,20,.58)');shade.addColorStop(.35,'rgba(3,10,20,0)');shade.addColorStop(.6,'rgba(3,10,20,.05)');shade.addColorStop(1,'rgba(3,10,20,.92)');x.fillStyle=shade;x.fillRect(0,0,1080,1920);
  x.fillStyle='#fff';x.font='500 32px system-ui';x.fillText(new Date(created).toLocaleString('it-IT',{day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'}),72,125,936);
  x.font='700 58px system-ui';const words=city.name.split(' ');let line='',lines=[];for(const word of words){if(x.measureText((line+' '+word).trim()).width>936&&line){lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);lines=lines.slice(0,3);lines.forEach((l,i)=>x.fillText(l,72,1360+i*72,936));
  x.font='700 128px system-ui';x.fillText(current?valueText(current.temperature_2m,'°'):'—°',72,1690,936);x.font='500 38px system-ui';x.fillText(current?weatherName(current.weather_code):'Meteo non disponibile',72,1750,936);x.font='400 23px system-ui';x.fillStyle='#d6e3f0';x.fillText(current?'Meteo Open-Meteo · '+String(current.time||'').replace('T',' '):'Foto della community',72,1795,936);x.fillStyle='#fff';x.font='700 30px system-ui';x.fillText('MeteoSocial',72,1855);x.fillStyle='#ff9a4d';x.fillRect(72,1870,64,5);
  blob=await asBlob(canvas);if(!dialog.isConnected)return;url=URL.createObjectURL(blob);dialog.querySelector('.postcard-preview').innerHTML=`<img src="${url}" width="1080" height="1920" alt="La tua cartolina del cielo di ${esc(city.name)}">`;
  dialog.querySelector('.postcard-actions').innerHTML=`<h1>Il tuo cielo</h1><p>${esc(city.name)} · formato storia 9:16</p><div class="postcard-export"><a class="button" href="${url}" download="meteosocial-il-tuo-cielo.jpg">Scarica</a><button data-postcard-share>Condividi</button></div><label for="postcard-kind">Che tempo vedi?</label><select id="postcard-kind"><option value="">Scegli il cielo</option>${['Cielo sereno','Pioggia','Neve','Vento','Grandine','Allagamento'].map(k=>`<option>${k}</option>`).join('')}</select><button class="sky-primary" data-postcard-publish disabled>Pubblica nella community</button><p class="postcard-privacy">Visibile per 2 ore nella zona approssimata. La foto non conserva i dati GPS.</p><p class="postcard-status" role="status"></p>`;
  const status=text=>{if(dialog.isConnected)dialog.querySelector('.postcard-status').textContent=text};
  dialog.querySelector('#postcard-kind').onchange=e=>{phenomenon=e.target.value;dialog.querySelector('[data-postcard-publish]').disabled=!phenomenon||busy||published};
  dialog.querySelector('[data-postcard-share]').onclick=async()=>{const f=new File([blob],'meteosocial-il-tuo-cielo.jpg',{type:'image/jpeg'});try{if(navigator.canShare?.({files:[f]})){await navigator.share({files:[f],title:'Il mio cielo · MeteoSocial'});status('')}else status('Scarica la cartolina e aprila in Instagram o TikTok.')}catch(e){if(e.name!=='AbortError')status('Condivisione non disponibile: usa Scarica.')}};
  dialog.querySelector('[data-postcard-publish]').onclick=async e=>{if(busy||published||!phenomenon)return;busy=true;const button=e.currentTarget;button.disabled=true;status('Pubblico il tuo cielo…');try{const photo=await fotoDataURL(blob,1050000);let name='Una voce del cielo';try{name=localStorage.getItem('meteosocial-sky-name')||name}catch{}const result=await sendObservation({id,observedAt:created,name,latitude:city.latitude,longitude:city.longitude,city:city.name,consent:true,level:0,options:[],phenomenon,photo});published=true;button.textContent=result.queued?'Salvata sul dispositivo':'Pubblicata';status(result.queued?'Verrà inviata appena torni online, entro 2 ore.':'Il tuo cielo è nella community e sulla mappa.');reportHaptic('success',e.isTrusted)}catch(err){status(err.message);if(err.status===401&&!dialog.querySelector('[data-postcard-login]')){const login=document.createElement('button');login.dataset.postcardLogin='true';login.textContent='Accedi';login.onclick=()=>ctx.login();dialog.querySelector('.postcard-actions').append(login)}reportHaptic('error',e.isTrusted)}finally{busy=false;if(!published)button.disabled=false}};
 }catch(e){if(dialog.isConnected)dialog.querySelector('.postcard-status').textContent=e.message||'Non riesco a leggere questa foto. Prova un’altra immagine.'}
}
